/// What an inline box moves, and how a paragraph follows it: padding, margin, borders and the font of a
/// `motion.span` take space along the line, so each frame lays the paragraph out again. The positions are those
/// headless Chrome reports for the same style moved by a paused animation (`fixtures/span-motion-oracle.json`,
/// regenerated by `fixtures/span-motion-oracle.sh`). Also the gestures of a span (`whileHover`, `whileTap`,
/// `whileFocus`, `whileInView`), motion values in its style, and the props it takes and ignores.

import fs from "fs"
import path from "path"
import React from "react"
import { fileURLToPath } from "url"
import { describe, expect, it } from "vitest"
import { animate, motion, motionValue, useMotionValue } from "../index.js"
import type { MotionValue } from "../index.js"
import { createTestRoot, hasNativeTestRenderer } from "../testing.js"
import { readLogicalPixels, SHOTS_DIR } from "./test-utils.js"

const describeNative = hasNativeTestRenderer ? describe : describe.skip

interface Sample {
  box: [number, number, number, number]
  next: [number, number, number, number] | null
  height: number
  font: string
}
interface OracleCase {
  width: number
  samples: Record<string, Sample>
}

const ORACLE: Record<string, OracleCase> = JSON.parse(
  fs.readFileSync(path.resolve(path.dirname(fileURLToPath(import.meta.url)), "fixtures/span-motion-oracle.json"), "utf8")
).cases

const TEXT = { fontSize: 16, lineHeight: "20px", fontFamily: "Menlo", color: "#000000" } as const
const LINEAR = { duration: 1, ease: "linear" } as const
const RED = "#ff0000"
const BLUE = "#0000ff"

function setup(node: React.ReactNode, width = 300) {
  const testRoot = createTestRoot({ width: 400, height: 200 })
  const renderer = testRoot.renderer
  renderer.clockPause()
  testRoot.render(
    <div style={{ width: 400, height: 200, backgroundColor: "#ffffff" }}>
      <text testId="p" style={{ ...TEXT, width }}>
        {node}
      </text>
    </div>
  )
  const bounds = (testId: string) => {
    renderer.flush()
    return renderer.getElementBounds(renderer.findByTestId(testId)!.id)!
  }
  let shots = 0
  return {
    testRoot,
    renderer,
    bounds,
    /** The left edge of `testId` in the paragraph, which a span before it moves. */
    left: (testId: string) => bounds(testId).x - bounds("p").x,
    height: () => bounds("p").height,
    /** The pixel `dx`, `dy` from the top left corner of the paragraph. */
    at: (dx: number, dy: number) => {
      const file = `${SHOTS_DIR}/span-motion-${shots++}.png`
      renderer.captureScreenshot(file)
      const box = bounds("p")
      return readLogicalPixels(file, renderer).at(Math.floor(box.x + dx), Math.floor(box.y + dy)).slice(0, 3)
    },
    /** One frame, with the events it produced delivered. */
    advance: (ms: number) => {
      renderer.clockFastForward(ms)
      renderer.flush()
      renderer.dispatchNativeEvents()
    },
  }
}

/** gpui measures a text to the next whole pixel, so a box is up to a pixel from Chrome's. */
const NEAR = 1.5

describeNative("a motion.span moves the space along its line, as Chrome lays it out", () => {
  const cases: Array<[string, Record<string, unknown>, React.CSSProperties?]> = [
    ["padding of a span moves what follows it", { paddingLeft: [0, 40], paddingRight: [0, 20] }],
    ["margin of a span moves what follows it", { marginLeft: [0, 30], marginRight: [0, 10] }],
    [
      "border width of a span moves what follows it",
      { borderLeftWidth: [0, 8], borderRightWidth: [0, 4] },
      { borderStyle: "solid", borderColor: RED, borderWidth: 0 },
    ],
    ["font size of a span moves what follows it and grows the line", { fontSize: [16, 32] }],
  ]
  for (const [name, keys, style] of cases) {
    it(name, () => {
      const initial = Object.fromEntries(Object.entries(keys).map(([key, [from]]) => [key, from]))
      const target = Object.fromEntries(Object.entries(keys).map(([key, [, to]]) => [key, to]))
      const page = setup(
        <>
          <motion.span testId="s" style={style} initial={initial as never} animate={target as never} transition={LINEAR}>
            aaaa
          </motion.span>
          <span testId="n">bbbb</span>
        </>
      )
      let elapsed = 0
      for (const time of [0, 0.25, 0.5, 0.75, 1]) {
        page.advance(time * 1000 - elapsed)
        elapsed = time * 1000
        const chrome = ORACLE[name]!.samples[String(time)]!
        expect(page.left("n"), `${name} at ${time}`).toBeGreaterThan(chrome.next![0] - NEAR)
        expect(page.left("n"), `${name} at ${time}`).toBeLessThan(chrome.next![0] + NEAR)
        expect(Math.abs(page.height() - chrome.height), `the height of the line at ${time}`).toBeLessThanOrEqual(1)
      }
      page.testRoot.unmount()
    })
  }

  for (const [name, keys] of [
    ["padding rewraps a paragraph", { paddingLeft: [0, 60] }],
    ["font size rewraps a paragraph", { fontSize: [16, 24] }],
  ] as const) {
    it(name, () => {
      const page = setup(
        <>
          aaaa{" "}
          <motion.span
            testId="s"
            initial={Object.fromEntries(Object.entries(keys).map(([key, [from]]) => [key, from])) as never}
            animate={Object.fromEntries(Object.entries(keys).map(([key, [, to]]) => [key, to])) as never}
            transition={LINEAR}
          >
            bbbb
          </motion.span>{" "}
          cccc
        </>,
        ORACLE[name]!.width
      )
      let elapsed = 0
      for (const time of [0, 0.25, 0.5, 0.75, 1]) {
        page.advance(time * 1000 - elapsed)
        elapsed = time * 1000
        const chrome = ORACLE[name]!.samples[String(time)]!
        expect(Math.abs(page.height() - chrome.height), `${name}: the paragraph is ${page.height()} high at ${time}, Chrome's is ${chrome.height}`).toBeLessThanOrEqual(1)
      }
      page.testRoot.unmount()
    })
  }
})

describeNative("a CSS transition on the style of a span", () => {
  it("moves its padding and the text after it", () => {
    const style = (padding: number) => ({ paddingLeft: padding, transition: "padding-left 1s linear" })
    const testRoot = createTestRoot({ width: 400, height: 200 })
    const renderer = testRoot.renderer
    renderer.clockPause()
    const tree = (padding: number) => (
      <div style={{ width: 400, height: 200 }}>
        <text testId="p" style={TEXT}>
          <span testId="s" style={style(padding)}>aaaa</span>
          <span testId="n">bbbb</span>
        </text>
      </div>
    )
    testRoot.render(tree(0))
    renderer.flush()
    testRoot.render(tree(40))
    renderer.clockFastForward(500)
    renderer.flush()
    const left = renderer.getElementBounds(renderer.findByTestId("n")!.id)!.x - renderer.getElementBounds(renderer.findByTestId("p")!.id)!.x
    // Only the left padding moves: what follows is where Chrome has it without the right one.
    const chrome = ORACLE["padding of a span moves what follows it"]!.samples["0"]!.next![0]! + 20
    expect(left).toBeGreaterThan(chrome - NEAR)
    expect(left).toBeLessThan(chrome + NEAR)
    testRoot.unmount()
  })
})

describeNative("motion values in the style of a span", () => {
  it("move what a span can show", () => {
    let padding!: MotionValue<number>
    let opacity!: MotionValue<number>
    function App() {
      padding = useMotionValue(0)
      opacity = useMotionValue(1)
      return (
        <>
          <span testId="s" style={{ paddingLeft: padding, opacity, backgroundColor: RED, color: BLUE }}>
            aaaa
          </span>
          <span testId="n">bbbb</span>
        </>
      )
    }
    const page = setup(<App />)
    const before = page.left("n")
    animate(padding, 40, LINEAR)
    page.advance(500)
    expect(page.left("n") - before).toBeCloseTo(20, 0)
    page.advance(1000)
    expect(page.left("n") - before).toBeCloseTo(40, 0)
    // Opacity is a group: the text over its own background does not show the background twice.
    opacity.set(0.5)
    page.renderer.flush()
    const box = page.bounds("s")
    const p = page.bounds("p")
    const [r, g, b] = page.at(box.x - p.x + 4, 10)
    expect([r, g, b]).toEqual([255, 128, 128])
    page.testRoot.unmount()
  })

  it("take the transforms and keep them off the span", () => {
    const x = motionValue(0)
    const page = setup(
      <>
        <motion.span testId="s" style={{ x, scale: motionValue(2) } as never} animate={{ x: 100, scale: 3, rotate: 45 }}>
          aaaa
        </motion.span>
        <span testId="n">bbbb</span>
      </>
    )
    const before = page.bounds("s")
    x.set(80)
    page.advance(1000)
    expect(page.bounds("s")).toEqual(before)
    expect(page.left("n")).toBeCloseTo(ORACLE["padding of a span moves what follows it"]!.samples["0"]!.next![0], 0)
    page.testRoot.unmount()
  })

  it("throw for a property a span does not have, and name it", () => {
    const errors: unknown[] = []
    const testRoot = createTestRoot({ onUncaughtError: (error) => errors.push(error) })
    try {
      testRoot.render(
        <text>
          <span style={{ width: motionValue(10) as never }}>aaaa</span>
        </text>
      )
    } catch (error) {
      errors.push(error)
    }
    testRoot.unmount()
    expect(errors).toHaveLength(1)
    expect((errors[0] as Error).message).toContain("style.width")
  })
})

describeNative("whileHover, whileTap and whileFocus on a motion.span", () => {
  const paddings = { paddingLeft: 40, paddingRight: 20 }

  function hoverable(extra: Record<string, unknown> = {}) {
    return setup(
      <>
        <motion.span
          testId="s"
          style={{ color: RED }}
          whileHover={{ ...paddings, color: BLUE }}
          transition={LINEAR}
          {...extra}
        >
          aaaa
        </motion.span>
        <span testId="n">bbbb</span>
      </>
    )
  }

  it("goes to the hover target while the pointer is over it, and back", () => {
    const page = hoverable()
    const rest = page.left("n")
    const box = page.bounds("s")
    page.renderer.nativeSimulateMouseMove(box.x + 4, box.y + 8)
    // The animation starts at the frame that sees the pointer there.
    page.advance(1)
    page.advance(499)
    const chrome = ORACLE["padding of a span moves what follows it"]!.samples["0.5"]!.next![0]!
    expect(page.left("n")).toBeGreaterThan(chrome - NEAR)
    expect(page.left("n")).toBeLessThan(chrome + NEAR)
    // Between the red it has and the blue it goes to.
    const bounds = page.bounds("s")
    const ink = page.at(bounds.x - page.bounds("p").x + 40 + 3, 10)
    expect(ink).toBeDefined()
    page.advance(500)
    expect(page.left("n")).toBeGreaterThan(rest + 60 - NEAR)

    page.renderer.nativeSimulateMouseMove(300, 150)
    page.advance(1)
    page.advance(499)
    expect(page.left("n")).toBeGreaterThan(chrome - NEAR)
    expect(page.left("n")).toBeLessThan(chrome + NEAR)
    page.advance(500)
    expect(page.left("n")).toBeCloseTo(rest, 0)
    page.testRoot.unmount()
  })

  it("takes the transition that the target carries for its own animation", () => {
    const page = setup(
      <>
        <motion.span
          testId="s"
          whileHover={{ paddingLeft: 40, transition: { duration: 4, ease: "linear" } }}
          transition={LINEAR}
        >
          aaaa
        </motion.span>
        <span testId="n">bbbb</span>
      </>
    )
    const rest = page.left("n")
    const box = page.bounds("s")
    page.renderer.nativeSimulateMouseMove(box.x + 4, box.y + 8)
    page.advance(1)
    page.advance(1000)
    expect(page.left("n") - rest).toBeCloseTo(10, 0)
    page.testRoot.unmount()
  })

  it("answers to a press with whileTap, which wins over whileHover", () => {
    const page = setup(
      <>
        <motion.span testId="s" whileHover={{ paddingLeft: 10 }} whileTap={{ paddingLeft: 30 }} transition={{ duration: 0 }}>
          aaaa
        </motion.span>
        <span testId="n">bbbb</span>
      </>
    )
    const rest = page.left("n")
    const box = page.bounds("s")
    page.renderer.nativeSimulateMouseMove(box.x + 4, box.y + 8)
    page.advance(10)
    expect(page.left("n") - rest).toBeCloseTo(10, 0)
    page.renderer.nativeSimulateMouseDown(box.x + 4, box.y + 8)
    page.advance(10)
    expect(page.left("n") - rest).toBeCloseTo(30, 0)
    page.renderer.nativeSimulateMouseUp(box.x + 4, box.y + 8)
    page.advance(10)
    expect(page.left("n") - rest).toBeCloseTo(10, 0)
    page.testRoot.unmount()
  })

  it("answers to focus that :focus-visible matches with whileFocus", () => {
    const page = setup(
      <>
        <motion.span testId="s" tabIndex={0} whileFocus={{ paddingLeft: 20 }} transition={{ duration: 0 }}>
          aaaa
        </motion.span>
        <span testId="n" tabIndex={0}>bbbb</span>
      </>
    )
    const rest = page.left("n")
    page.renderer.simulateKeystrokes("Tab")
    page.advance(10)
    expect(page.left("n") - rest).toBeCloseTo(20, 0)
    page.renderer.simulateKeystrokes("Tab")
    page.advance(10)
    expect(page.left("n")).toBeCloseTo(rest, 0)
    page.testRoot.unmount()
  })
})

describeNative("whileInView on a motion.span", () => {
  function scene(spacer: number, extra: Record<string, unknown> = {}) {
    return (
      <div style={{ width: 400, height: 200 }}>
        <div style={{ height: spacer }} />
        <text testId="p" style={TEXT}>
          <motion.span
            testId="s"
            whileInView={{ paddingLeft: 30 }}
            transition={{ duration: 0 }}
            {...extra}
          >
            aaaa
          </motion.span>
          <span testId="n">bbbb</span>
        </text>
      </div>
    )
  }

  function observe(extra: Record<string, unknown> = {}) {
    const testRoot = createTestRoot({ width: 400, height: 200 })
    const renderer = testRoot.renderer
    renderer.clockPause()
    testRoot.render(scene(600, extra))
    const left = () => {
      renderer.flush()
      return renderer.getElementBounds(renderer.findByTestId("n")!.id)!.x - renderer.getElementBounds(renderer.findByTestId("p")!.id)!.x
    }
    const settle = () => {
      for (let step = 0; step < 8; step++) {
        renderer.clockFastForward(20)
        renderer.flush()
        renderer.dispatchNativeEvents()
      }
    }
    return { testRoot, renderer, left, settle, show: (spacer: number) => testRoot.render(scene(spacer, extra)) }
  }

  it("animates to its target once the span is in view, and back when it leaves", () => {
    const page = observe()
    page.settle()
    const rest = page.left()
    page.show(0)
    page.settle()
    expect(page.left() - rest).toBeCloseTo(30, 0)
    page.show(600)
    page.settle()
    expect(page.left()).toBeCloseTo(rest, 0)
    page.testRoot.unmount()
  })

  it("stays in view with viewport.once", () => {
    const page = observe({ viewport: { once: true } })
    page.settle()
    const rest = page.left()
    page.show(0)
    page.settle()
    expect(page.left() - rest).toBeCloseTo(30, 0)
    page.show(600)
    page.settle()
    expect(page.left() - rest).toBeCloseTo(30, 0)
    page.testRoot.unmount()
  })
})

describeNative("what a motion.span ignores", () => {
  it("takes layout and drag props and moves nothing with them", () => {
    const calls: string[] = []
    const page = setup(
      <>
        <motion.span
          testId="s"
          layout
          layoutId="chip"
          layoutDependency={1}
          drag
          dragConstraints={{ left: 0 }}
          whileDrag={{ color: RED }}
          onLayoutAnimationStart={() => calls.push("start")}
          animate={{ color: BLUE }}
        >
          aaaa
        </motion.span>
        <span testId="n">bbbb</span>
      </>
    )
    const before = page.left("n")
    page.advance(1000)
    expect(page.left("n")).toBe(before)
    expect(calls).toEqual([])
    page.testRoot.unmount()
  })
})
